// Deja los valores listos para la consulta INSERT de BigQuery.
// Van como texto porque el nodo manda los parámetros como STRING; la consulta convierte el puntaje a número.
const r = $input.item.json;
const puntaje = String(r.puntaje ?? '').trim();
if (!/^[1-5]$/.test(puntaje)) throw new Error('El puntaje tiene que ser un número del 1 al 5.');

return {
  json: {
    equipo: String(r.equipo ?? '').trim().slice(0, 100),
    linea: String(r.linea ?? '').trim(),
    puntaje,
    comentario: String(r.comentario ?? '').trim().slice(0, 1000),
  },
};

// La consulta devuelve una fila por línea con cuántas respuestas hay y su promedio.
const filas = $input.all().map((i) => i.json).filter((f) => f.linea);
const total = filas.reduce((s, f) => s + Number(f.respuestas ?? 0), 0);
const lista = filas.map((f) => `<li><b>${f.linea}</b>: ${f.respuestas} ${Number(f.respuestas) === 1 ? 'respuesta' : 'respuestas'}, promedio ${f.promedio} de 5</li>`).join('');
return [
  {
    json: {
      total,
      total_texto: total === 1 ? '1 respuesta' : `${total} respuestas`,
      filas,
      html: lista ? `<ul>${lista}</ul>` : '<p>Todavía no hay respuestas.</p>',
    },
  },
];

